1	/**
2	 * `Static()` — the static-side sibling of `Reactive()`.
3	 *
4	 * Lazily binds every visible static method of a capability class without
5	 * touching the raw class, so methods stay referentially stable and safe to
6	 * retain as callbacks (routers, watchers, command handlers) while the
7	 * selected `Class` slot remains replaceable by a kernel/plugin.
8	 *
9	 * This is the namespace pattern's backend adapter: canonical namespace +
10	 * mutable `Class` slot + late reads, for STATELESS capability classes (a
11	 * function bag). Never wrap stateful/reactive instance classes with it — use
12	 * `Reactive()` for those; `Static()` operates on the single class object and
13	 * has no instance dimension.
14	 *
15	 * Ships from `ivue/utils` (not the reactive core) so the primary `ivue`
16	 * entry stays minimal.
17	 */
18	export type ClassConstructor = new (...arguments_: any[]) => any;
19	
20	export function Static<Class extends ClassConstructor>(targetClass: Class): Class {
21	  const SelectedClass = class extends targetClass {};
22	  const visitedKeys = new Set<PropertyKey>();
23	
24	  for (
25	    let currentClass: ClassConstructor = targetClass;
26	    currentClass !== Function.prototype;
27	    currentClass = Object.getPrototypeOf(currentClass)
28	  ) {
29	    for (const key of Reflect.ownKeys(currentClass)) {
30	      if (visitedKeys.has(key)) continue;
31	      visitedKeys.add(key);
32	
33	      const descriptor = Object.getOwnPropertyDescriptor(currentClass, key)!;
34	      if (typeof descriptor.value !== 'function') continue;
35	      const method = descriptor.value;
36	
37	      Object.defineProperty(SelectedClass, key, {
38	        configurable: true,
39	        enumerable: descriptor.enumerable,
40	        get(this: ClassConstructor) {
41	          const boundMethod = method.bind(this);
42	          Object.defineProperty(this, key, { ...descriptor, value: boundMethod });
43	          return boundMethod;
44	        },
45	      });
46	    }
47	  }
48	
49	  return SelectedClass as Class;
50	}
